<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';require_once __DIR__.'/includes/service_engine.php';login_required();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post('action');$id=post('id');if($action==='delete'&&$id!==''){try{$pdo->prepare("DELETE FROM `medical_service` WHERE `medicalservice_id`=?")->execute([$id]);flash('success','Medical Service deleted.');}catch(Throwable $e){flash('error','This record is in use and cannot be deleted.');}}redirect('medical.php');}
$rows=$pdo->query('SELECT * FROM `medical_service` ORDER BY `medicalservice_id` DESC')->fetchAll();page_header('Medical Service','medical');?>
<div class="page-head"><div><h1>Medical Service</h1><p class="muted">Manage Medical Service records and related guest services.</p></div><a class="btn primary" href="medical_form.php">Add Medical Service</a></div>
<section class="card table-wrap"><table><thead><tr><th>ID</th><th>Open</th><th>Close</th><th>Details</th><th>Actions</th></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><td><?=e($r['medicalservice_id'])?></td><td><?=e($r['medicalservice_open_time'])?></td><td><?=e($r['medicalservice_close_time'])?></td><td><?=e($r['medicalservice_details'])?></td><td class="actions"><a href="medical_form.php?id=<?=urlencode((string)$r['medicalservice_id'])?>">Edit</a><a href="medical_service.php?id=<?=urlencode((string)$r['medicalservice_id'])?>">Add Service</a><form method="post" onsubmit="return confirm('Are you sure?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($r['medicalservice_id'])?>"><button class="danger-link">Delete</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">No records.</td></tr><?php endif;?></tbody></table></section><?php page_footer();?>
